function camerasPage(){if(st.detail){let c=cameras.find(x=>x.id===decodeURIComponent(st.detail));if(c)return head(c.name,'Detalhes de dispositivo de vídeo e vínculos com ativos.',`${linkBtn('Voltar às câmeras','cameras')} ${btn('Editar câmera','edit-camera','','settings')} ${btn('Buscar gravação','recordings','primary','history')}`)+`<div class="section-grid">${panel('Visualização de demonstração',cameraTile(c,true)+`<p class="hint mt12">Somente arte ilustrativa, sem streaming.</p>`)}${panel('Detalhes do dispositivo',`<div class="subtle-list">${val('Identificador',c.id)}${val('Local / ativo',c.site)}${val('Categoria',c.detail)}${val('Fabricante de exemplo',c.brand)}${val('Estado',c.state)}${val('Protocolo','ONVIF / RTSP (proposta)')}</div><div class="btn-row mt16">${btn('Testar conexão','diagnostic','','wifi')} ${btn('Associar ativo','link-camera','','plus')}</div>`)}</div>`;}return head('Câmeras e NVRs','Inventário de câmeras IP, MDVRs embarcados e gravadores, com permissões e estados.',`${btn('Novo NVR','new-nvr','','plus')} ${btn('Adicionar câmera','new-camera','primary','plus')}`)+`<div class="toolbar"><div class="search-field">${icon('search','sm')}<input data-search="camera-row" placeholder="Buscar câmera, local ou modelo"/></div>${btn('Descoberta ONVIF','discover','','wifi')}${linkBtn('Abrir videowall','video')}</div>`+tb(['Câmera','Local / vínculo','Tipo / fabricante','Situação','Protocolos propostos','Ação'],cameras.map(c=>row([cell(c.name,c.id),esc(c.site),esc(c.brand),badge(c.state),'RTSP / ONVIF',linkBtn('Abrir','cameras',c.id)],`class="filterable camera-row" data-search-value="${esc((c.name+' '+c.site+' '+c.brand).toLowerCase())}"`)))+`<div class="mt16">${panel('Servidores de mídia e gravação',`<div class="tri-grid">${[['VMS PRINCIPAL','Planejado','MediaMTX / WebRTC'],['NVR PORTO','Não conectado','Rede privada / gateway'],['MDVR FROTA','Não conectado','Vídeo embarcado 4G']].map(x=>`<div class="catalog-card"><div class="catalog-icon">${icon('database')}</div><div><strong>${x[0]}</strong><small>${x[1]}</small><small>${x[2]}</small></div></div>`).join('')}</div>`)}</div>`;}
function cargoPage(){if(st.detail){let c=cargos.find(x=>x.id===decodeURIComponent(st.detail));if(c)return head('Contêiner '+c.id,'Proteção de abertura, lacre, localização e histórico de eventos.',`${linkBtn('Voltar aos contêineres','cargo')} ${btn('Editar cadastro','edit-cargo','','settings')} ${btn('Solicitar autorização','new-authorization','primary','lock')}`)+`<div class="metric-grid">${stat('PORTA',c.door,'Sensor ilustrativo','box',c.door==='Aberto'?'red':'green')}${stat('LACRE',c.seal,'Equipamento associado','lock')}${stat('BATERIA',c.battery+'%','Indicador simulado','zap')}${stat('RISCO',c.risk,'Classificação de exemplo','shield',c.risk==='Crítico'?'red':'green')}</div><div class="section-grid">${panel('Monitoramento de localização',mapWidget({compact:true}),`<span class="chip warn">Local não verificado</span>`)}${panel('Ficha do contêiner',`${containerIllustration()}<div class="subtle-list">${val('Identificador',c.id)}${val('Rota',c.trip)}${val('Cliente',c.owner)}${val('Estado da porta',c.door)}${val('Lacre eletrônico',c.seal)}${val('Última comunicação',c.last)}</div><div class="btn-row mt16">${linkBtn('Lacres','seals')} ${linkBtn('Autorizações','authorizations')}</div>`)}</div><div class="two-grid mt16">${panel('Eventos e histórico',`<div class="list-lines"><div class="list-line"><div class="alert-ico">${icon('lock','sm')}</div><div class="list-text"><strong>Evento de sensor / lacre</strong><small>Registro ilustrativo de integridade e abertura</small></div></div><div class="list-line"><div class="alert-ico">${icon('location','sm')}</div><div class="list-text"><strong>Última posição conhecida</strong><small>Requer validação de conectividade em produção</small></div></div></div>`,linkBtn('Ver alertas','alerts'))}${panel('CFTV associado',cameraTile(cameras[2]),linkBtn('Ver videowall','video'))}</div>`;}return head('Proteção de contêineres','Integridade de portas e lacres, alertas de violação e correlação com rastreamento e CFTV.',`${btn('Cadastrar contêiner','new-cargo','primary','plus')} ${btn('Criar regra de proteção','new-rule','','shield')}`)+`<div class="metric-grid">${stat('CONTÊINERES','86','Inventário fictício','box')}${stat('PROTEGIDOS','81','Integridade ilustrativa','shield','green')}${stat('VIOLAÇÃO','01','Exige análise','warn','red')}${stat('SEM SINAL','04','Estado não confirmado','wifi','amber')}</div><div class="toolbar">${tab(['Todos','Seguro','Crítico','Sem sinal','Atenção'],st.cargoFilter,'cargo-filter')}${linkBtn('Lacres eletrônicos','seals')}${linkBtn('Autorizações','authorizations')}</div><div class="cargo-grid">${cargos.filter(c=>st.cargoFilter==='Todos'||c.risk===st.cargoFilter).map(c=>`<div class="card cargo-card">${containerIllustration()}<div class="row-between"><div><span class="mono tiny muted">ID DO CONTÊINER</span><h2 style="margin:6px 0">${c.id}</h2></div>${badge(c.risk)}</div><div class="hint" style="margin:7px 0 16px">${esc(c.trip)}</div><div class="subtle-list">${val('Porta',c.door)}${val('Lacre',c.seal)}${val('Bateria',c.battery+'%')}${val('Último contato',c.last)}</div><div style="margin:14px 0">${progress(c.battery)}</div><div class="btn-row">${linkBtn('Monitorar','cargo',c.id)}${btn('Ver vídeo','open-video-tile','mini','video')}</div></div>`).join('')}</div>`;}
function sealsPage(){return head('Lacres eletrônicos e sensores','Gestão de integridade física, sensores magnéticos, cadeados inteligentes e diagnósticos.',`${btn('Cadastrar lacre','new-seal','primary','plus')} ${btn('Testar sensor','diagnostic','','activity')}`)+`<div class="metric-grid">${stat('LACRES CADASTRADOS','86','Demonstração','lock')}${stat('ÍNTEGROS','80','Sensores simulados','check','green')}${stat('VIOLAÇÕES','01','Evento crítico fictício','warn','red')}${stat('BATERIA BAIXA','05','Exigem manutenção','zap','amber')}</div><div class="toolbar"><div class="search-field">${icon('search','sm')}<input data-search="seal-row" placeholder="Buscar lacre ou contêiner"/></div>${btn('Importar sensores','import-demo','','export')}${linkBtn('Monitorar contêineres','cargo')}</div>`+tb(['Lacre / Sensor','Tecnologia','Contêiner vinculado','Integridade','Energia','Comunicação','Ação'],seals.map(s=>row([`<strong>${s.id}</strong>`,esc(s.type),esc(s.linked),badge(s.state),`${s.battery}%`,s.comm,`<button class="btn mini" data-action="seal-detail" data-id="${s.id}">Ver sensor</button>`],`class="filterable seal-row" data-search-value="${esc((s.id+' '+s.linked).toLowerCase())}"`)))+`<div class="two-grid mt16">${panel('Regras de violação',`<div class="subtle-list">${val('Rompimento de lacre','Crítico')}${val('Porta fora de área','Crítico')}${val('Perda de comunicação','Aviso')}${val('Bateria baixa','Manutenção')}</div>`,btn('Configurar','new-rule','','settings'))}${panel('Compatibilidade física',`<p class="hint">A integração dependerá do modelo do sensor, interface digital, fabricante, rede disponível, tipo de contêiner e requisitos de segurança e homologação.</p><div class="mt16">${linkBtn('Catálogo de dispositivos','devices')}</div>`)}</div>`;}
function authorizationsPage(){const requests=[{id:'AUT-301',cargo:'MSKU-100234-5',requester:'Juliana Ribeiro',place:'Terminal Porto',window:'17:00–18:00',state:'Pendente'},{id:'AUT-302',cargo:'TGHU-887120-2',requester:'Carlos Almeida',place:'Base Logística',window:'18:30–19:30',state:'Em análise'},{id:'AUT-303',cargo:'CMAU-452113-6',requester:'Marina Souza',place:'Armazém Central',window:'15:00–16:00',state:'Autorizado'}];return head('Autorizações de abertura','Fluxo de solicitação, dupla validação, janela de tempo e geocerca para abertura de cargas.',`${btn('Solicitar abertura','new-authorization','primary','plus')} ${btn('Definir políticas','policies','','shield')}`)+`<div class="notice-banner">${icon('lock','sm')} Este módulo é somente visual. Nenhum cadeado, lacre ou trava física pode ser aberto ou desbloqueado aqui.</div><div class="metric-grid">${stat('SOLICITAÇÕES','23','Período fictício','document')}${stat('PENDENTES','02','Aguardando validação','clock','amber')}${stat('AUTORIZADAS','19','Exemplo do fluxo','check','green')}${stat('RECUSADAS','02','Conforme política fictícia','close','red')}</div>${panel('Solicitações recentes',requests.map(r=>`<div class="approval"><div><div class="row-between" style="justify-content:flex-start"><strong>${r.id}</strong>${badge(st.simApprovals.has(r.id)?'Autorizado (demo)':r.state)}</div><small>Contêiner ${esc(r.cargo)} • ${esc(r.requester)}</small><small>Geocerca: ${esc(r.place)} | Janela: ${esc(r.window)}</small></div><div class="btn-row"><button class="btn mini" data-action="authorization-review" data-id="${r.id}">Analisar</button><button class="btn mini primary" data-action="authorization-approve" data-id="${r.id}">Simular aprovação</button></div></div>`).join(''))}<div class="two-grid mt16">${panel('Condições exigidas',`<div class="subtle-list">${val('Geocerca permitida','Obrigatória')}${val('Janela temporal','Obrigatória')}${val('Identidade do aprovador','Validada (proposta)')}${val('Dupla aprovação','Ativável')}${val('Comprovação no lacre','Exigível')}</div>`)}${panel('Controles de segurança',`<p class="hint">No sistema definitivo, a autorização será registrada com identidade, data/hora, motivo, permissões, estado da comunicação, trilha de auditoria e confirmação independente do dispositivo. O acesso à interface não equivale à abertura física.</p>`,linkBtn('Auditoria','audit'))}</div>`;}
function telemetryPage(){let items=['Velocidade','Tensão','Temperatura','Combustível','Ignição','Bateria'];return head('Telemetria avançada','Visualização sincronizada de séries temporais e eventos operacionais, inspirada no conceito NASA Open MCT.',`${btn('Personalizar painel','customize','','settings')} ${btn('Exportar amostra','export-demo','primary','download')}`)+`<div class="toolbar"><select class="filter-select" style="min-width:250px"><option>Caminhão Amazônia 01</option>${assets.slice(1).map(a=>`<option>${esc(a.name)}</option>`).join('')}</select><button class="btn" data-action="date-range">${icon('calendar','sm')} Últimas 24 horas</button>${tab(items,st.telemetry,'telemetry-mode')}</div><div class="metric-grid">${stat('VELOCIDADE ATUAL','63 km/h','Valor fictício','route')}${stat('TENSÃO EXTERNA','13,4 V','Valor fictício','zap','green')}${stat('TEMPERATURA','26,8 °C','Valor fictício','activity')}${stat('COMUNICAÇÃO','Simulada','Sem gateway conectado','wifi','amber')}</div>${panel('Análise temporal • '+st.telemetry,`<div class="chart-area" style="height:315px">${sparkLine(items.indexOf(st.telemetry))}</div><div class="row-between mt12"><span class="hint">00:00</span><span class="hint">06:00</span><span class="hint">12:00</span><span class="hint">18:00</span><span class="hint">23:59</span></div><div class="separator"></div><p class="hint">Curva sintética gerada para ilustrar o componente. Não representa medições, telemetria ou integrações da NASA.</p>`,`<span class="chip info">Open MCT · integração planejada</span>`)}<div class="two-grid mt16">${panel('Sensores associados',`<div class="subtle-list">${val('Ignição','Ligada (demo)')}${val('Odômetro','42.156 km (demo)')}${val('Temperatura do compartimento','18,5 °C (demo)')}${val('Porta do compartimento','Fechada (demo)')}${val('Sinal GPS','Ilustrativo')}</div>`)}${panel('Correlação de eventos',`<div class="list-lines"><div class="list-line"><div class="alert-ico">${icon('flag','sm')}</div><div class="list-text"><strong>Frenagem brusca</strong><small>Evento sintético · 16:18</small></div></div><div class="list-line"><div class="alert-ico">${icon('fence','sm')}</div><div class="list-text"><strong>Entrada em zona</strong><small>Evento sintético · 16:42</small></div></div></div>`,linkBtn('Reproduzir viagem','replay'))}</div>`;}
function aiPage(){return head('AMBRAXIS Intelligence','Copiloto de operações com consultas em linguagem natural — respostas locais e roteirizadas nesta demonstração.',`${btn('Novo diálogo','reset-chat','','plus')} ${btn('Configurar fontes','ai-sources','','settings')}`)+`<div class="section-grid">${panel('Assistente de operações',`<div class="chatbox"><div class="chat-prompts">${['Quais ativos estão sem sinal?','Existe violação de contêiner?','Resumo dos alertas críticos','Como funciona o CFTV integrado?'].map(q=>`<button data-chat-prompt="${esc(q)}">${esc(q)}</button>`).join('')}</div><div class="chat-messages" id="chat-messages">${st.chat.map(x=>`<div class="chat-msg ${x.who==='user'?'user':'bot'}">${esc(x.msg)}</div>`).join('')}</div><form class="chat-input" id="chat-form"><input id="chat-question" placeholder="Pergunte sobre a operação (resposta demonstrativa)..." aria-label="Mensagem ao copiloto"/><button class="btn primary" type="submit">${icon('send','sm')} Enviar</button></form></div>`,`<span class="chip warn">IA não conectada</span>`)}${panel('O que a IA poderá fazer',`<div class="list-lines">${[['Análise de frotas','Consultar veículos, paradas e anomalias'],['Proteção de cargas','Correlacionar lacre, geocerca e vídeo'],['Assistente de ocorrências','Preparar resumos com evidências'],['Busca por linguagem natural','Consultar eventos mediante permissão'],['Previsões auditáveis','Modelos especializados e validação humana']].map(([title,txt])=>`<div class="list-line"><div class="alert-ico" style="background:#193f42;color:#5ce1cb">${icon('brain','sm')}</div><div class="list-text"><strong>${title}</strong><small>${txt}</small></div></div>`).join('')}</div><div class="notice-banner mt16" style="margin:0">${icon('info','sm')} Não executar comandos físicos automaticamente. IA apenas recomenda; decisões sensíveis exigem autorização humana.</div>`,'')}</div>`;}
function reportsPage(){let reports=[['Resumo operacional','Ativos, alertas, comunicação e indicadores','grid'],['Histórico de viagens','Percursos, paradas e horários','route'],['Telemetria e sensores','Séries e eventos técnicos','activity'],['Relatório de CFTV','Câmeras, acessos e ocorrências','video'],['Proteção de cargas','Aberturas, lacres e autorizações','lock'],['Desempenho da frota','Jornada, paradas e utilização','chart'],['Auditoria de acessos','Operadores e ações registradas','file'],['Financeiro / SaaS','Planos, clientes e mensalidades','credit']];return head('Centro de relatórios','Modelos de relatórios operacionais, gerenciais e de conformidade com exportação demonstrativa.',`${btn('Agendar relatório','schedule-report','','calendar')} ${btn('Criar modelo','new-report','primary','plus')}`)+`<div class="toolbar"><select class="filter-select" data-report-period>${['Hoje','7 dias','30 dias','90 dias'].map(p=>`<option ${p===st.reportPeriod?'selected':''}>${p}</option>`).join('')}</select><button class="btn" data-action="date-range">${icon('calendar','sm')} Selecionar período</button>${btn('Exportar dados de exemplo','export-demo','','download')}</div><div class="tri-grid">${reports.map(([title,txt,ic])=>`<div class="card padded"><div class="row-between"><span class="catalog-icon">${icon(ic)}</span><span class="chip info">MODELO</span></div><h2 class="mt16">${title}</h2><p class="hint" style="min-height:38px">${txt}</p><div class="btn-row mt16"><button class="btn mini primary" data-action="report-preview" data-name="${esc(title)}">${icon('eye','sm')} Visualizar</button><button class="btn mini" data-action="export-demo">${icon('download','sm')} CSV demo</button></div></div>`).join('')}</div>`;}
function heatmapPage(){return head('Inteligência territorial','Análise espacial de eventos e concentração operacional baseada em células hexagonais (conceito Uber H3).',`${btn('Escolher camadas','layers','','layers')} ${btn('Exportar mapa','export-image','primary','download')}`)+`<div class="metric-grid">${stat('ÁREAS ANALISADAS','324','Células ilustrativas','hex')}${stat('ZONAS CRÍTICAS','12','Concentração simulada','warn','red')}${stat('ÍNDICE DE ATIVIDADE','78,4','Pontuação fictícia','activity')}${stat('ÚLTIMA ANÁLISE','—','Não processada','clock','amber')}</div><div class="section-grid">${panel('Mapa de densidade',`${mapWidget({markers:false,hex:true})}<div class="hex-legend"><span><i class="legend-box" style="background:#32cec6"></i>Menor densidade</span><span><i class="legend-box" style="background:#f7b265"></i>Média densidade</span><span><i class="legend-box" style="background:#ef776b"></i>Maior densidade</span></div>`,`<span class="chip info">Visualização ilustrativa</span>`)}${panel('Camadas disponíveis',`<div class="settings-line"><div><strong>Eventos de segurança</strong><small>Concentração de alertas</small></div><button class="switch on" data-toggle-setting="Camada eventos" aria-label="Alternar camada"></button></div><div class="settings-line"><div><strong>Ativos em circulação</strong><small>Volume por zona</small></div><button class="switch on" data-toggle-setting="Camada frota" aria-label="Alternar camada"></button></div><div class="settings-line"><div><strong>Ocorrências de lacres</strong><small>Risco de carga</small></div><button class="switch" data-toggle-setting="Camada carga" aria-label="Alternar camada"></button></div><div class="separator"></div><p class="hint">Na operação definitiva, os cálculos serão feitos sobre dados autorizados, com agregação que evite exposição desnecessária de pessoas.</p>`)}</div>`;}
function customersPage(){if(st.detail){let c=customers.find(x=>x.id===decodeURIComponent(st.detail));if(c)return head(c.name,'Organização e gestão de recursos do ambiente multiempresa.',`${linkBtn('Voltar aos clientes','customers')} ${btn('Editar empresa','edit-customer','primary','settings')}`)+`<div class="metric-grid">${stat('ATIVOS',c.assets,'Cadastro de exemplo','truck')}${stat('USUÁRIOS',c.users,'Usuários de exemplo','users')}${stat('PLANO',c.plan,'Assinatura fictícia','credit')}${stat('STATUS',c.state,'Sem operação ativa','shield')}</div><div class="two-grid">${panel('Dados da organização',`<div class="subtle-list">${val('Identificador',c.id)}${val('Razão de exibição',c.name)}${val('Segmento',c.sector)}${val('Plano',c.plan)}${val('Estado',c.state)}${val('Região','Brasil / Manaus (demo)')}</div>`,btn('Editar cadastro','edit-customer','','settings'))}${panel('Controle de acesso',`<p class="hint">No produto definitivo, cada empresa terá separação lógica dos dados, administradores próprios, limites de dispositivos, permissões por função e trilha de auditoria.</p><div class="btn-row mt22">${linkBtn('Usuários','users')}${linkBtn('Assinaturas','billing')}</div>`)}</div>`;}return head('Clientes e organizações','Gestão de empresas independentes, administradores, limites e marca branca.',`${btn('Convidar cliente','invite-customer','','send')} ${btn('Cadastrar empresa','new-customer','primary','plus')}`)+`<div class="metric-grid">${stat('EMPRESAS','36','Exemplo de base SaaS','building')}${stat('CLIENTES ATIVOS','32','Indicador fictício','check','green')}${stat('EM AVALIAÇÃO','04','Teste demonstrativo','clock','amber')}${stat('DISPOSITIVOS','248','Contagem fictícia','cpu')}</div><div class="toolbar"><div class="search-field">${icon('search','sm')}<input data-search="customer-row" placeholder="Buscar empresa ou setor"/></div>${btn('Exportar amostra','export-demo','','download')}</div>`+tb(['Empresa','Segmento','Ativos','Usuários','Plano','Status','Ação'],customers.map(c=>row([cell(c.name,c.id),c.sector,c.assets,c.users,`<span class="chip info">${c.plan}</span>`,badge(c.state),linkBtn('Gerenciar','customers',c.id)],`class="filterable customer-row" data-search-value="${esc((c.name+' '+c.sector).toLowerCase())}"`)))+`<div class="mt16">${panel('Estrutura multiempresa',`<p class="hint">Isolamento por organização, papéis e permissões, governança de equipamentos, API e módulos contratados. Cada empresa poderá visualizar somente os ativos autorizados, sem acesso a dados de outros clientes.</p>`)}</div>`;}
function billingPage(){const plans=[{name:'AMBRAXIS BASIC',price:'Sob consulta',features:['Rastreamento GPS','Mapa e histórico','Alertas e geocercas','Painel do cliente','Suporte padrão']},{name:'AMBRAXIS PRO',price:'Sob consulta',features:['Tudo do Basic','Telemetria avançada','Proteção de contêineres','Integração de câmeras','Relatórios profissionais']},{name:'AMBRAXIS ENTERPRISE',price:'Personalizado',features:['Tudo do Pro','Marca branca','Múltiplas empresas','API e SSO corporativo','Central 24h e módulos avançados']}];return head('Planos, assinaturas e cobrança','Estrutura comercial do AMBRAXIS, com planos configuráveis e faturamento ainda não conectado.',`${btn('Simular proposta','proposal','','file')} ${btn('Cadastrar plano','new-plan','primary','plus')}`)+`<div class="notice-banner">${icon('info','sm')} Preços não definidos. Esta página não processa pagamentos, emite documentos fiscais nem gera cobranças reais.</div><div class="plan-grid">${plans.map((p,i)=>`<div class="card plan ${i===1?'popular':''}">${i===1?'<span class="chip good" style="margin-bottom:14px">Plano intermediário</span>':''}<h2>${p.name}</h2><strong>${p.price}</strong><p class="hint">Configuração demonstrativa por cliente.</p><ul>${p.features.map(f=>`<li>${icon('check','sm')} ${f}</li>`).join('')}</ul><button class="btn ${i===1?'primary':''}" style="width:100%" data-action="plan-config" data-name="${p.name}">Configurar plano ${icon('arrow','sm')}</button></div>`).join('')}</div><div class="two-grid mt16">${panel('Visão de assinaturas',`<div class="subtle-list">${val('Assinaturas de exemplo','36')}${val('Em avaliação','04')}${val('Inadimplência','Não calculada')}${val('Receita mensal','Não implementada')}</div>`,btn('Visualizar contratos','billing-contracts','','file'))}${panel('Módulos vendáveis',`<div class="subtle-list">${val('GPS e frota','Módulo base')}${val('AMBRAXIS VIDEO','Complementar')}${val('AMBRAXIS CARGO GUARD','Complementar')}${val('AMBRAXIS Intelligence','Complementar')}${val('Marca branca / API','Enterprise')}</div>`,btn('Editar pacotes','new-plan','','settings'))}</div>`;}
function usersPage(){return head('Usuários, equipes e permissões','Perfis de operadores, técnicos, administradores e clientes, com segregação multiempresa.',`${btn('Configurar papéis','roles','','shield')} ${btn('Convidar usuário','new-user','primary','plus')}`)+`<div class="metric-grid">${stat('USUÁRIOS','118','Cadastro fictício','users')}${stat('ADMINISTRADORES','07','Perfis sensíveis','key')}${stat('OPERADORES','68','Cenário ilustrativo','video')}${stat('CONVITES PENDENTES','03','Sem emails enviados','clock','amber')}</div><div class="toolbar"><div class="search-field">${icon('search','sm')}<input data-search="user-row" placeholder="Buscar usuário ou empresa"/></div>${btn('Matriz de permissões','roles','','lock')}</div>`+tb(['Usuário','E-mail de exemplo','Empresa','Perfil','Estado','Ação'],users.map(u=>row([cell(u.name,u.id),esc(u.email),esc(u.company),`<span class="chip info">${esc(u.role)}</span>`,badge(u.state),`<button class="btn mini" data-action="user-detail" data-id="${u.id}">Gerenciar</button>`],`class="filterable user-row" data-search-value="${esc((u.name+' '+u.email+' '+u.company).toLowerCase())}"`)))+`<div class="mt16">${panel('Permissões de alto risco',`<div class="tri-grid">${[['Abertura de carga','Exigir regras e identidade'],['Comandos remotos','Autorização adicional'],['Exportações','Restringir por função']].map(x=>`<div class="catalog-card"><div class="catalog-icon">${icon('shield')}</div><div><strong>${x[0]}</strong><small>${x[1]}</small></div></div>`).join('')}</div>`)}</div>`;}
function integrationsPage(){const items=[
['Traccar','Gateway e decodificação de GPS','cpu','GPS / protocolo'],['NASA Open MCT','Visualização de telemetria','activity','Telemetria'],['Google Maps Platform','Rotas, trânsito e geocodificação','map','Mapas'],['MapLibre GL JS','Renderização de mapas','layers','Mapas'],['Microsoft Azure Maps','Geolocalização e clima','globe','Mapas'],['Amazon Location','Posicionamento e geocercas','location','Geografia'],['AWS IoT Core','Mensageria de dispositivos','wifi','IoT'],['MediaMTX','Servidor de streaming','video','CFTV'],['ONVIF / RTSP','Conectividade de câmeras','camera','CFTV'],['Google OR-Tools','Otimização matemática','route','Logística'],['Uber H3','Índices geoespaciais','hex','Inteligência'],['Firebase Cloud Messaging','Notificações push','bell','Comunicação'],['Cloudflare','Proteção de aplicação','shield','Segurança'],['WhatsApp Business','Mensageria corporativa','send','Comunicação'],['OpenAI / Gemini','Copiloto de IA','brain','Inteligência'],['Microsoft Entra','Identidade empresarial','key','Identidade']];return head('Integrações e APIs','Catálogo de conectores previstos para o produto. Todos estão desabilitados nesta demonstração.',`${btn('Adicionar integração','new-integration','primary','plus')} ${btn('Documentar API','api-docs','','file')}`)+`<div class="metric-grid">${stat('CONECTORES NO CATÁLOGO',String(items.length),'Referências de arquitetura','plug')}${stat('ATIVOS EM PRODUÇÃO','0','Nenhuma integração real','check','amber')}${stat('WEBHOOKS ATIVOS','0','Sem endpoints externos','route')}${stat('CREDENCIAIS SALVAS','0','Nenhuma chave coletada','key','green')}</div><div class="toolbar"><div class="search-field">${icon('search','sm')}<input data-search="integration-card" placeholder="Filtrar pelo nome ou categoria"/></div>${btn('Visualizar API','api-docs','','file')}${btn('Simular webhook','webhook-demo','','zap')}</div><div class="tri-grid">${items.map(([name,description,ic,cat])=>`<div class="catalog-card filterable integration-card" data-search-value="${esc((name+' '+cat).toLowerCase())}"><div class="catalog-icon">${icon(ic)}</div><div style="min-width:0;flex:1"><strong>${esc(name)}</strong><small>${esc(description)}</small><small>${esc(cat)} · Não conectado</small></div><button class="btn mini" data-action="integration-detail" data-name="${esc(name)}">${icon('settings','sm')}</button></div>`).join('')}</div>`;}
function auditPage(){return head('Auditoria e rastreabilidade','Registro de visualizações, operações e eventos de segurança com requisitos de integridade e governança.',`${btn('Política de retenção','retention','','shield')} ${btn('Exportar amostra','export-demo','primary','download')}`)+`<div class="metric-grid">${stat('EVENTOS AUDITADOS','1.832','Registros sintéticos','file')}${stat('ACESSOS ADMIN','124','Simulação de atividade','users')}${stat('COMANDOS REMOTOS','0','Não disponíveis','lock','green')}${stat('INTEGRIDADE','Não aferida','Sem servidor de evidências','shield','amber')}</div><div class="toolbar"><div class="search-field">${icon('search','sm')}<input data-search="audit-row" placeholder="Filtrar ator, evento ou recurso"/></div><button class="btn" data-action="date-range">${icon('calendar','sm')} Hoje</button></div>`+tb(['Horário','Ator / origem','Ação','Recurso','Criticidade'],audit.map(x=>row([`<span class="mono">${x[0]}</span>`,x[1],cell(x[2]),x[3],badge(x[4])],`class="filterable audit-row" data-search-value="${esc(x.join(' ').toLowerCase())}"`)))+`<div class="mt16">${panel('Governança e evidências',`<p class="hint">No produto real: logs append-only, referências de eventos e evidências, sincronização temporal, retenção configurável, segregação entre empresas, alertas de alteração e mecanismos de verificação de integridade.</p>`)}</div>`;}
function settingsPage(){return head('Configurações do ambiente','Preferências demonstrativas, identidade visual, alertas e políticas operacionais.',`${btn('Restaurar padrão visual','reset-settings','','refresh')} ${btn('Simular salvamento','save-settings','primary','save')}`)+`<div class="two-grid">${panel('Preferências gerais',`<div class="form-grid"><div class="field"><label>Nome da plataforma</label><input value="AMBRAXIS" aria-label="Nome da plataforma"/></div><div class="field"><label>Fuso horário</label><select><option>America/Manaus (UTC−4)</option><option>America/Sao_Paulo</option></select></div><div class="field"><label>Idioma</label><select><option>Português (Brasil)</option><option>English (visual)</option></select></div><div class="field"><label>Unidade de velocidade</label><select><option>km/h</option><option>mph</option></select></div><div class="field span2"><label>Modo de interface</label><div class="btn-row">${btn('Alternar claro/escuro','theme','','sun')}${linkBtn('Ver central','overview')}</div></div></div>`)}${panel('Notificações e segurança',`${['Notificações no navegador','Alertas sonoros','Modo de economia de dados','Acesso com MFA obrigatório','Exigir autorização dupla','Exibir coordenadas completas'].map(k=>`<div class="settings-line"><div><strong>${k}</strong><small>Somente preferência visual demonstrativa</small></div><button class="switch ${st.setting[k]?'on':''}" data-toggle-setting="${esc(k)}" aria-label="Alternar ${esc(k)}"></button></div>`).join('')}`)}</div><div class="two-grid mt16">${panel('Identidade de marca branca',`<div class="form-grid"><div class="field"><label>Cor de destaque</label><select><option>Ciano profissional</option><option>Azul</option><option>Verde</option></select></div><div class="field"><label>Domínio</label><input placeholder="cliente.exemplo.com" /></div></div><div class="mt16">${btn('Visualizar personalização','preview-brand','','eye')}</div>`)}${panel('Regras para operação real',`<div class="list-lines">${[['Segregação multiempresa','Controle de acesso por organização'],['Canais de alerta','Confirmação e reenvio de notificações'],['Aprovação para comandos','Perfis, motivos e dupla autorização'],['Retenção de vídeo e GPS','Política legal e governança de dados']].map(x=>`<div class="list-line"><span class="catalog-icon">${icon('shield','sm')}</span><div class="list-text"><strong>${x[0]}</strong><small>${x[1]}</small></div></div>`).join('')}</div>`)}</div>`;}
function helpPage(){let questions=[['O botão SOS ou antifurto aciona equipamentos?','Não. Armar, desarmar, simular violação, reconhecer, encerrar e SOS operam somente na memória desta aba. Nenhum comando físico ou pedido de ajuda é enviado.'],['Este protótipo rastreia algum veículo?','Não. Todas as posições, placas, identificadores, trajetos e indicadores são fictícios. O arquivo não se conecta a rastreadores nem a satélites.'],['Os botões realmente abrem portões ou contêineres?','Não. Todas as ações de autorização, bloqueio, diagnóstico e controle abrem apenas janelas de demonstração. Nenhum comando é enviado.'],['Existe transmissão real de câmeras?','Não. O videowall usa ilustrações vetoriais criadas para o protótipo. No produto definitivo serão usados gateways de mídia e permissões específicas.'],['O copiloto utiliza alguma IA externa?','Não. As mensagens são respostas locais e predefinidas. Nenhum texto é enviado a modelos externos.'],['Os cadastros são salvos?','Não há banco de dados nem armazenamento persistente. Formulários apenas mostram a experiência de cadastro.'],['Como será a arquitetura futura?','Um backend de negócio isolado, gateway de GPS (Traccar), Postgres/PostGIS, serviços de vídeo, fila de eventos e aplicação frontend independente.'],['Posso usar este modelo comercialmente?','O código demonstrativo pode servir como ponto de partida visual. Antes de comercializar, é necessário desenvolver autenticação, segurança, LGPD, integrações, testes, contratos e homologação de dispositivos.'],['Funciona sem internet?','Sim, para as telas demonstrativas, pois HTML, CSS, JavaScript, desenhos de mapas e prévias de CFTV estão no pacote e não exigem APIs externas.']];return head('Ajuda, documentação e escopo','Guia de navegação e limites desta demonstração navegável.',`${btn('Mapa de telas','site-map','primary','grid')} ${btn('Arquitetura técnica','architecture','','database')}`)+`<div class="section-grid">${panel('Perguntas frequentes',questions.map(([q,a],i)=>`<div class="faq-item"><button data-faq="${i}">${esc(q)} ${icon(st.faqOpen===i?'up':'down','sm')}</button>${st.faqOpen===i?`<p>${esc(a)}</p>`:''}</div>`).join(''))}${panel('Mapa dos módulos',groups.map(g=>`<div style="margin-bottom:18px"><h3 class="muted" style="letter-spacing:1px;margin-bottom:9px">${g[0]}</h3><div class="stack" style="gap:7px">${g[1].map(([id,label,ic])=>`<button class="row-between btn ghost" style="width:100%;justify-content:flex-start" data-nav="${id}">${icon(ic,'sm')} ${label} <span style="margin-left:auto">${icon('chevron','sm')}</span></button>`).join('')}</div></div>`).join(''))}</div><div class="mt16">${panel('Princípios da plataforma',`<div class="tri-grid">${[['Privacidade','Rastreamento somente autorizado'],['Segurança','Comandos críticos com dupla validação'],['Observabilidade','Distinguir online e última posição'],['Modularidade','Mudar provedor sem refazer produto'],['Escalabilidade','Fila e histórico particionáveis'],['Experiência','Uma central para GPS, vídeo e carga']].map(([a,b])=>`<div class="catalog-card"><span class="catalog-icon">${icon('check')}</span><div><strong>${a}</strong><small>${b}</small></div></div>`).join('')}</div>`)}</div>`;}

// AMBRAXIS / ANTI-FURTO — protótipo local, sem comandos de hardware e sem rede.
const antiStamp=()=>new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Manaus',hour:'2-digit',minute:'2-digit'}).format(new Date());
const antiAsset=()=>assets.find(a=>a.id===st.antiAsset)||assets[0];
const antiOnline=a=>a.status!=='Sem sinal';
const antiOpenFor=id=>st.antiIncidents.filter(e=>e.asset===id&&e.state!=='Encerrado');
const antiMode=a=>!antiOnline(a)?'Sem comunicação':antiOpenFor(a.id).length?'Em alarme':st.antiArmed[a.id]?'Protegido':'Desarmado';
function antiRecord(title,asset,text='',level='normal'){
 st.antiHistory.unshift({when:antiStamp(),title,asset,text,level});
 if(st.antiHistory.length>60)st.antiHistory.length=60;
 audit.unshift([antiStamp()+':00','Admin Demo',title,asset,level==='critical'?'Crítico':'Demonstração']);
}
function antiRaise(kind,id){
 let a=assets.find(x=>x.id===id);
 if(!a)return;
 let incident={id:'AF-'+String(st.antiSeq++).padStart(3,'0'),asset:id,assetName:a.name,kind,when:antiStamp(),state:'Novo',note:'',severity:'Crítico'};
 st.antiIncidents.unshift(incident);
 alertItems.unshift({id:'ALT-'+incident.id,name:kind==='SOS/Pânico'?'SOS / Pânico — acionamento manual (simulação)':'Possível violação antifurto (simulação)',source:a.name,severity:'Crítico',at:incident.when,state:'Novo',type:'Antifurto'});
 antiRecord(kind,id,'Ocorrência fictícia '+incident.id+' · Sem notificações externas', 'critical');
}
const antiControl=(label,description,action,ic,extra='',disabled=false)=>`<button type="button" class="anti-action ${extra}" data-action="${action}" data-id="${esc(st.antiAsset)}" ${disabled?'disabled':''}>${icon(ic)}<strong>${esc(label)}</strong><small>${esc(description)}</small></button>`;
function antitheftPage(){
 const a=antiAsset(), online=antiOnline(a),armed=!!st.antiArmed[a.id],mode=antiMode(a),open=antiOpenFor(a.id);
 const history=st.antiHistory.filter(e=>e.asset===a.id).slice(0,10);
 const nProtected=assets.filter(x=>antiOnline(x)&&st.antiArmed[x.id]).length;
 const nOpen=st.antiIncidents.filter(x=>x.state!=='Encerrado').length;
 let ids=assets.map(x=>`<option value="${esc(x.id)}" ${x.id===a.id?'selected':''}>${esc(x.name)} · ${esc(x.plate)}</option>`).join('');
 return head('Antifurto e SOS','Proteção de veículos, botão de emergência, prevenção de violação e protocolo de atendimento — tudo simulado, sem conexão real.',`${linkBtn('Central de alertas','alerts')} ${linkBtn('Ver veículo','fleet',a.id)} `,'AMBRAXIS / SEGURANÇA ATIVA')+
 `<div class="anti-warning">${icon('warn','sm')} <strong>AMBIENTE DEMONSTRATIVO:</strong> nenhum botão chama polícia, envia notificações, aciona sirenes, bloqueia ignição ou altera veículos. Os eventos desaparecem ao recarregar o arquivo.</div>`+
 `<div class="metric-grid">${stat('PROTEÇÃO ARMADA',String(nProtected).padStart(2,'0'),'Estados fictícios','shield','green')}${stat('EM ALERTA',String(nOpen).padStart(2,'0'),'Ocorrências na aba','warn',nOpen?'red':'')}${stat('SEM SINAL',String(assets.filter(x=>!antiOnline(x)).length).padStart(2,'0'),'Não presume veículo seguro','wifi','amber')}${stat('DISPOSITIVOS','09','Ativos de demonstração','truck')}</div>`+
 `<div class="card padded mb16"><div class="toolbar" style="margin-bottom:14px"><div class="field" style="flex:1;min-width:220px;max-width:510px"><label for="anti-select">Selecione o veículo monitorado</label><select id="anti-select" data-anti-asset>${ids}</select></div><div style="align-self:end;display:flex;gap:8px;flex-wrap:wrap">${linkBtn('Localização','live')} ${linkBtn('Câmeras','video')} ${linkBtn('Histórico de alertas','alerts')}</div></div><div class="anti-hero"><div><div class="overline">${esc(a.id)} · ${esc(a.plate)}</div><h2>${esc(a.name)}</h2><p>${esc(a.loc)} · ${esc(a.tenant)}<br>Estado de comunicação: ${esc(a.status)} (fictício)</p></div><div class="anti-status ${mode==='Protegido'?'':mode==='Em alarme'?'alarm':'off'}"><span class="light"></span><span>${esc(mode.toUpperCase())}</span></div></div><div class="anti-actions">${antiControl('Armar proteção','Ativa o estado protegido na demonstração','anti-arm','shield','',armed||!online)}${antiControl('Desarmar proteção','Solicita confirmação e justificativa','anti-disarm','unlock','',!armed)}${antiControl('Simular violação','Movimento/ignição não autorizados','anti-violation','warn','',!armed||!online)}${antiControl('BOTÃO SOS / PÂNICO','Simular alerta crítico manual','anti-sos','bell','emergency')}</div><div class="hint">Proteção armada não equivale à confirmação de funcionamento de um rastreador real. Equipamentos sem sinal não podem garantir alerta em tempo real.</div></div>`+
 `<div class="section-grid">${panel('Localização e correlação',mapWidget({selected:a.id,compact:true})+`<p class="hint mt12">Mapa esquemático e última posição fictícia; não representa monitoramento GPS em tempo real.</p>`,linkBtn('Abrir mapa','live'))}${panel('Situação de proteção',`<div class="subtle-list">${val('Modo',mode)}${val('Veículo',a.name)}${val('Comunicação',a.status)}${val('Ignição (exemplo)',a.speed>0?'Ligada':'Desligada')}${val('Eventos em atendimento',String(open.length))}${val('Comandos físicos','Desativados')}</div><div class="separator"></div><p class="hint">O mecanismo real exigirá autenticação forte, sensores homologados, geocercas, dupla validação para comandos sensíveis e políticas de escalonamento.</p>`)}</div>`+
 `<div class="two-grid mt16">${panel('Ocorrências do antifurto',st.antiIncidents.filter(x=>x.asset===a.id).slice(0,10).map(e=>`<div class="anti-incident"><div style="flex:1;min-width:0"><strong>${esc(e.kind)} · ${esc(e.id)}</strong><small>${esc(e.when)} · ${esc(e.assetName)} · ${esc(e.state)}${e.note?' · '+esc(e.note):''}</small></div><div class="btn-row">${badge(e.state)}${e.state==='Novo'?`<button class="btn mini" data-action="anti-ack" data-id="${esc(e.id)}">Reconhecer</button>`:''}${e.state!=='Encerrado'?`<button class="btn mini" data-action="anti-resolve" data-id="${esc(e.id)}">Encerrar</button>`:''}</div></div>`).join('')||`<div class="empty">Nenhuma ocorrência deste veículo nesta sessão. Experimente o botão SOS ou simule uma violação.</div>`,linkBtn('Central de alertas','alerts'))}${panel('Linha do tempo',`<div>${history.map(h=>`<div class="anti-log ${h.level==='critical'?'critical':''}"><strong>${esc(h.title)}</strong><small>${esc(h.when)} · ${esc(h.text)}</small></div>`).join('')||`<div class="empty">Ainda não há eventos para este veículo. Ative o modo antifurto para testar.</div>`}</div>`)}</div>`+
 `<div class="mt16">${panel('Políticas simuladas de detecção',`<div class="anti-tool-grid">${[['movement','Movimento não autorizado','Deslocamento fora da janela de uso'],['ignition','Ignição inesperada','Partida quando o veículo estiver protegido'],['geofence','Saída de geocerca','Rompimento de perímetro permitido'],['power','Corte de alimentação','Falha ou tentativa de desligamento do dispositivo']].map(([id,name,desc])=>`<div class="anti-rule"><div><strong>${esc(name)}</strong><small>${esc(desc)}</small></div><button class="switch ${st.antiRules[id]?'on':''}" aria-label="Alternar regra ${esc(name)}" aria-pressed="${st.antiRules[id]?'true':'false'}" data-anti-rule="${id}"></button></div>`).join('')}</div><p class="hint mt16">As chaves alteram apenas a aparência e o estado em memória; nenhuma regra operacional está conectada. No sistema real os dispositivos devem ser homologados para cada evento.</p>`,btn('Fluxo de atendimento','anti-protocol','','file'))}</div>`;
}

